PRAGMA foreign_keys=ON;
CREATE TABLE users(id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, role TEXT NOT NULL CHECK(role IN ('tenant','landlord')));
CREATE TABLE tenancies(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), address TEXT NOT NULL, landlord_name TEXT NOT NULL, landlord_email TEXT NOT NULL, rent_cents INTEGER NOT NULL CHECK(rent_cents>0), deposit_cents INTEGER NOT NULL CHECK(deposit_cents>=0), start_date TEXT NOT NULL, end_date TEXT, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','ended')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE reports(id TEXT PRIMARY KEY, tenancy_id TEXT NOT NULL REFERENCES tenancies(id) ON DELETE CASCADE, type TEXT NOT NULL CHECK(type IN ('move-in','move-out')), finalised_at TEXT, UNIQUE(tenancy_id,type));
CREATE TABLE room_entries(id TEXT PRIMARY KEY, report_id TEXT NOT NULL REFERENCES reports(id) ON DELETE CASCADE, room_name TEXT NOT NULL, condition TEXT NOT NULL CHECK(condition IN ('OK','minor issue','defect')), note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE photos(id TEXT PRIMARY KEY, room_entry_id TEXT NOT NULL REFERENCES room_entries(id) ON DELETE CASCADE, storage_key TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE addenda(id TEXT PRIMARY KEY, report_id TEXT NOT NULL REFERENCES reports(id) ON DELETE CASCADE, note TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE checklist_items(id TEXT PRIMARY KEY, tenancy_id TEXT NOT NULL REFERENCES tenancies(id) ON DELETE CASCADE, label TEXT NOT NULL, done INTEGER NOT NULL DEFAULT 0 CHECK(done IN (0,1)), done_at TEXT);
CREATE TABLE deposit_events(id TEXT PRIMARY KEY, tenancy_id TEXT NOT NULL REFERENCES tenancies(id) ON DELETE CASCADE, stage TEXT NOT NULL CHECK(stage IN ('Not yet moved out','Keys returned','Deposit requested','Returned in full','Returned in part','Disputed')), note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE deposit_settings(tenancy_id TEXT PRIMARY KEY REFERENCES tenancies(id) ON DELETE CASCADE, reminder_days INTEGER NOT NULL DEFAULT 14 CHECK(reminder_days>0));
